class TournamentBracket(dyui.Component):
    """A tournament bracket entry. Use it when showing one tournament bracket."""
    name = "tournament_bracket"
    id: str
    capacity: float
    city: str
    percent: float
    time: Optional[str] = None

    def render(self):
        return ui.Card(str(self.id), ui.Markdown("tournament bracket"))

